#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    // The original program expects exactly one argument.
    if (argc != 2) {
        return 0; // No output, matches original behavior for missing argument.
    }

    const char *input = argv[1];
    size_t input_len = strlen(input);
    if (input_len > 1024) {
        puts("TOO_LONG");
        return 0;
    }

    // Normalize: keep only alphanumeric characters, case‑insensitive (uppercase).
    char norm[1025]; // enough for all alnum chars (input <=1024)
    size_t n = 0;
    for (size_t i = 0; i < input_len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)toupper(c);
        }
    }
    norm[n] = '\0';

    // Palindrome test on the normalized string.
    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
